#include <iostream>
#include <vector>
#include <memory>
#include <string_view>

class SpaceObject {
public:
    virtual void draw() const = 0;
    virtual ~SpaceObject() = default;
};

class Martian : public SpaceObject {
public:
    void draw() const override {
        std::cout << "Martian: Drawing red alien with antennae.\n";
    }
};

class SpaceShip : public SpaceObject {
public:
    void draw() const override {
        std::cout << "SpaceShip: Drawing silver flying saucer.\n";
    }
};

class Mercurian : public SpaceObject {
public:
    void draw() const override {
        std::cout << "Mercurian: Drawing glowing gold explorer.\n";
    }
};

void renderScreen(const std::vector<std::unique_ptr<SpaceObject>>& scene) {
    for (const auto& obj : scene) {
        obj->draw();
    }
}

int main() {
    std::vector<std::unique_ptr<SpaceObject>> scene;
    scene.push_back(std::make_unique<Martian>());
    scene.push_back(std::make_unique<SpaceShip>());
    scene.push_back(std::make_unique<Mercurian>());

    std::cout << "Rendering screen objects:\n";
    renderScreen(scene);
    return 0;
}

#include <iostream>
#include <string>
#include <iomanip>

class CommissionEmployee {
public:
    CommissionEmployee(std::string first, std::string last, double sales, double rate)
        : firstName(std::move(first)), lastName(std::move(last)), grossSales(sales), commissionRate(rate) {}

    void print() const {
        std::cout << "commission employee: " << firstName << " " << lastName
                  << "\n  sales: " << grossSales
                  << ", rate: " << commissionRate << '\n';
    }

private:
    std::string firstName;
    std::string lastName;
    double grossSales;
    double commissionRate;
};

class BasePlusCommissionEmployee : public CommissionEmployee {
public:
    BasePlusCommissionEmployee(std::string first, std::string last, double sales, double rate, double salary)
        : CommissionEmployee(std::move(first), std::move(last), sales, rate), baseSalary(salary) {}

    void print() const {
        CommissionEmployee::print();
        std::cout << "  base salary: " << baseSalary << '\n';
    }

private:
    double baseSalary;
};

int main() {
    std::cout << std::fixed << std::setprecision(2);

    CommissionEmployee ce{"Sue", "Jones", 10000.0, 0.06};
    BasePlusCommissionEmployee bpce{"Bob", "Lewis", 5000.0, 0.04, 300.0};

    CommissionEmployee* cePtr = nullptr;
    BasePlusCommissionEmployee* bpcePtr = nullptr;

    // Base-class pointer -> Base-class object
    cePtr = &ce;
    std::cout << "[1] Base pointer -> Base object:\n";
    cePtr->print();

    // Derived-class pointer -> Derived-class object
    bpcePtr = &bpce;
    std::cout << "\n[2] Derived pointer -> Derived object:\n";
    bpcePtr->print();

    // Base-class pointer -> Derived-class object (Non-virtual call)
    cePtr = &bpce;
    std::cout << "\n[3] Base pointer -> Derived object (Calls base print):\n";
    cePtr->print(); // Notice base salary is omitted because print() is non-virtual

    return 0;
}
